/// Aether 内置页：DeepSeek 风格对话窗——对话区在上，输入框固定在底部；外观跟随系统
enum SermoHTML {
    static let aether = """
    <!doctype html><html lang="zh"><head><meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>QuotOS Aether</title>
    <style>
      * { box-sizing: border-box; }
      html,body { height:100%; margin:0; }
      body {
        font-family: -apple-system, "PingFang SC", system-ui, sans-serif;
        background:#ffffff; color:#1a1a1a; display:flex; flex-direction:column;
      }
      @media (prefers-color-scheme: dark) {
        body { background:#0f1115; color:#e8ebff; }
      }
      /* 顶部工具条 */
      .top {
        padding:8px 12px; flex:0 0 auto;
        border-bottom:1px solid rgba(128,128,128,.18);
        display:flex; align-items:center; gap:8px; flex-wrap:wrap;
      }
      .top .title { flex:1; font-size:12px; color:#8a8f9e; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
      .avatar { flex:0 0 auto; width:28px; height:28px; border-radius:50%; cursor:pointer; display:flex; align-items:center; justify-content:center; color:inherit; }
      .avatar svg { width:28px; height:28px; display:block; }
      .avatar img { width:28px; height:28px; display:block; border-radius:50%; }
      .avatar { overflow:hidden; }
      .avatar:hover { background:rgba(128,128,128,.14); }
      .avatar-picker { position:relative; flex:0 0 auto; }
      .avatar-menu {
        position:absolute; top:calc(100% + 6px); right:0; z-index:30;
        min-width:156px; padding:6px; border-radius:12px;
        background:rgba(250,250,252,.98); border:1px solid rgba(128,128,128,.18);
        box-shadow:0 8px 24px rgba(0,0,0,.16);
      }
      @media (prefers-color-scheme: dark) {
        .avatar-menu { background:rgba(28,30,40,.98); border-color:rgba(255,255,255,.12); box-shadow:0 8px 24px rgba(0,0,0,.5); }
      }
      .avatar-menu .mh { font-size:11px; color:#8a8f9e; padding:4px 8px 6px; }
      .avatar-opt { display:flex; align-items:center; gap:8px; padding:7px 8px; border-radius:8px; cursor:pointer; font-size:13px; }
      .avatar-opt:hover { background:rgba(128,128,128,.14); }
      .avatar-opt.active { background:rgba(74,108,255,.14); }
      .avatar-opt .sw { width:24px; height:24px; border-radius:50%; overflow:hidden; flex:0 0 auto; display:flex; align-items:center; justify-content:center; background:rgba(128,128,128,.12); }
      .avatar-opt .sw img { width:24px; height:24px; display:block; border-radius:50%; }
      .avatar-opt .nm { flex:1; }
      .avatar-opt .ck { display:none; color:#4a6cff; font-size:12px; }
      .avatar-opt.active .ck { display:inline; }
      .tbtn {
        flex:0 0 auto; font-size:12px; padding:5px 12px; border-radius:8px; cursor:pointer;
        background:transparent; border:1px solid rgba(128,128,128,.25); color:inherit;
      }
      .tbtn:hover { background:rgba(128,128,128,.12); }
      .tbtn.danger { color:#e05a5a; border-color:rgba(224,90,90,.4); }
      .tbtn.primary { background:#4a6cff; color:#fff; border-color:#4a6cff; }
      /* 历史对话抽屉 */
      .drawer {
        position:fixed; top:0; right:0; bottom:0; width:260px; max-width:80vw;
        background:#f6f7fa; border-left:1px solid rgba(128,128,128,.2);
        transform:translateX(100%); transition:transform .2s; z-index:10;
        display:flex; flex-direction:column;
      }
      @media (prefers-color-scheme: dark) { .drawer { background:#161a26; border-color:rgba(255,255,255,.1); } }
      .drawer.open { transform:translateX(0); }
      .drawer h3 { margin:0; padding:14px 14px 10px; font-size:13px; }
      .hist-list { flex:1; overflow-y:auto; padding:0 8px; }
      .hist-item {
        padding:10px; border-radius:10px; cursor:pointer; margin-bottom:4px;
        border:1px solid transparent;
      }
      .hist-item:hover { background:rgba(128,128,128,.1); }
      .hist-item.active { background:rgba(74,108,255,.12); border-color:rgba(74,108,255,.35); }
      .hist-item .ht { font-size:12px; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
      .hist-item .hs { font-size:11px; color:#8a8f9e; margin-top:3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
      .hist-empty { padding:20px 14px; font-size:12px; color:#8a8f9e; text-align:center; }
      .drawer .close { margin:8px; }
      .mask { position:fixed; inset:0; z-index:9; background:rgba(0,0,0,.15); display:none; }
      .mask.open { display:block; }
      /* 模式开关（Logos / Philo）并排，窄窗时竖排 */
      .mode-toggles {
        display:flex; flex-direction:row; align-items:center; justify-content:center;
        gap:18px; margin-top:8px;
      }
      .logos {
        display:flex; align-items:center; justify-content:center; gap:6px;
        font-size:11px; color:#8a8f9e; cursor:pointer; user-select:none;
      }
      .logo-switch {
        width:28px; height:16px; border-radius:9px; background:#c7c9d1; position:relative;
        transition:background .15s;
      }
      .logo-switch::after {
        content:""; position:absolute; top:2px; left:2px; width:12px; height:12px;
        border-radius:50%; background:#fff; transition:left .15s;
      }
      .logos.on { color:#4a6cff; }
      .logos.on .logo-switch { background:#4a6cff; }
      .logos.on .logo-switch::after { left:14px; }
      .input.logos-on { border-color:#4a6cff; }
      /* Philo 模式开关 */
      .philos {
        display:flex; align-items:center; justify-content:center; gap:6px;
        font-size:11px; color:#8a8f9e; cursor:pointer; user-select:none;
      }
      .philos.on { color:#7b5bff; }
      .philos.on .logo-switch { background:#7b5bff; }
      .philos.on .logo-switch::after { left:14px; }
      .input.philo-on { border-color:#7b5bff; }
      @media (max-width: 480px) {
        .mode-toggles { flex-direction:column; gap:8px; }
      }
      /* 对话区 */
      .chat { flex:1 1 auto; overflow-y:auto; padding:20px 12px; display:flex; flex-direction:column; gap:10px; }
      .empty { text-align:center; margin-top:16vh; color:#8a8f9e; }
      @media (prefers-color-scheme: dark) { .empty { color:#9aa3c7; } }
      .empty .dot { width:46px; height:46px; border-radius:50%; margin:0 auto 14px;
        background:linear-gradient(135deg,#5b6cff,#8f7bff); display:flex; align-items:center;
        justify-content:center; font-size:20px; color:#fff; }
      .empty p { font-size:13px; margin:0; }
      .row { display:flex; width:100%; }
      .row.user { justify-content:flex-end; }
      .row.ai { justify-content:flex-start; }
      .msg { max-width:75%; padding:9px 14px; border-radius:16px;
        font-size:14px; line-height:1.6; white-space:pre-wrap; word-break:break-word;
        overflow-wrap:anywhere; }
      .msg.user { background:#4a6cff; color:#fff; border-bottom-right-radius:5px; }
      .msg .time { display:block; font-size:10px; opacity:.6; margin-top:4px; }
      .msg.ai { background:#eceef3; color:#2a2f3f; border-bottom-left-radius:5px; }
      @media (prefers-color-scheme: dark) { .msg.ai { background:#232838; color:#dfe3f5; } }
      .msg.ai.thinking { color:#8a8f9e; font-style:italic; }
      .dots { display:inline-block; animation:blink 1s infinite; }
      @keyframes blink { 50% { opacity:.3; } }
      /* 底部输入区 */
      .composer { flex:0 0 auto; padding:12px 16px 16px; }
      .input {
        display:flex; align-items:flex-end; gap:8px; border-radius:18px;
        background:#f2f3f7; border:1px solid rgba(128,128,128,.2); padding:10px 10px 10px 14px;
      }
      @media (prefers-color-scheme: dark) {
        .input { background:#1c2030; border-color:rgba(255,255,255,.1); }
      }
      textarea {
        flex:1; background:transparent; border:none; outline:none; resize:none;
        color:inherit; font-size:14px; line-height:1.5; max-height:140px; font-family:inherit;
        /* 单行时与 34px 发送按钮等高，占位文字上下居中：上下各留 6.5px；
           border-box 让自动增高（height=scrollHeight，已含 padding）不累积误差。 */
        padding:6.5px 0; min-height:34px; box-sizing:border-box;
      }
      textarea::placeholder { color:#9aa0b4; }
      button.send {
        flex:0 0 auto; width:34px; height:34px; border-radius:50%; border:none;
        background:#4a6cff; color:#fff; font-size:16px; cursor:pointer;
        display:flex; align-items:center; justify-content:center;
      }
      button.send:disabled { background:#c7c9d1; }
      @media (prefers-color-scheme: dark) { button.send:disabled { background:#2a3050; } }
    </style></head>
    <body>
    <script>\(AetherPhiloData.js)</script>
      <div class="top">
        <div class="avatar" id="avatar"></div>
        <div class="title" id="title">新对话</div>
        <button class="tbtn primary" id="newchat">＋ 新建对话</button>
        <div class="avatar-picker">
          <button class="tbtn" id="avatarset" title="选择 Aether 形象">⚙ 形象</button>
          <div class="avatar-menu" id="avatarmenu" style="display:none"></div>
        </div>
        <button class="tbtn" id="history">历史对话</button>
        <button class="tbtn danger" id="clear">清空对话</button>
      </div>
      <div class="chat" id="chat"></div>
      <div class="mask" id="mask"></div>
      <div class="drawer" id="drawer">
        <h3>历史对话</h3>
        <div class="hist-list" id="histlist"></div>
        <button class="tbtn danger" id="clearAll">清空全部历史</button>
        <button class="tbtn close" id="closeDrawer">关闭</button>
      </div>
      <div class="composer">
        <div class="input" id="inputbox">
          <textarea id="ta" rows="1" placeholder="给 QuotOS Aether 发送消息…"></textarea>
          <button class="send" id="send" disabled>↑</button>
        </div>
        <div class="mode-toggles">
          <div class="logos" id="logos">
            <span class="logo-switch"></span>
            <span>Logos 模式</span>
          </div>
          <div class="philos" id="philos">
            <span class="logo-switch"></span>
            <span>Philo 模式</span>
          </div>
        </div>
      </div>
      <script>
        var CK = "aether.conversations";
        var CID = "aether.currentId";
        var chat = document.getElementById("chat");
        var ta = document.getElementById("ta");
        var send = document.getElementById("send");
        var drawer = document.getElementById("drawer");
        var mask = document.getElementById("mask");
        var logosOn = false;
        var philoOn = localStorage.getItem("aether.philoOn") === "1";
        var apiSeq = 0;
        var pendingApi = {};

        // ---- 预设数据（来自 Resources/aether_presets.json，运行期注入 window.__AETHER_PRESETS） ----
        var P = window.__AETHER_PRESETS || { avatarMap:{}, characters:{}, common:{ profanity:[], comfort:[], greeting:[] }, detection:{ crashWords:[], profaneWords:[], whitelist:[], identityTriggers:[] } };
        var DET = P.detection || {};
        var CHAR_KEY_BY_AVATAR = P.avatarMap || { male: "cecil", female: "aetheria", ghost: "nox" };
        var CHAR_NAME = {};
        for (var _ck in (P.characters || {})) { CHAR_NAME[_ck] = (P.characters[_ck] && P.characters[_ck].name) || _ck; }
        var CRASH_WORDS = DET.crashWords || [];
        var PROFANE_WORDS = DET.profaneWords || [];
        var WHITELIST = DET.whitelist || [];
        var PHILO_IDENTITY_TRIGGERS = DET.identityTriggers || [];

        function loadConvs() { try { return JSON.parse(localStorage.getItem(CK) || "[]"); } catch(e) { return []; } }
        function saveConvs(c) { localStorage.setItem(CK, JSON.stringify(c)); }
        function currentId() { return localStorage.getItem(CID); }
        function setCurrentId(id) { localStorage.setItem(CID, id); }
        function nowHM() {
          var n = new Date();
          return ("0"+n.getHours()).slice(-2)+":"+("0"+n.getMinutes()).slice(-2);
        }
        function curConv() {
          var cs = loadConvs();
          var id = currentId();
          for (var i=0;i<cs.length;i++) if (cs[i].id === id) return { list:cs, item:cs[i], idx:i };
          // 没有则新建
          var c = { id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), title:"新对话", messages:[], time: nowHM() };
          cs.unshift(c);
          saveConvs(cs); setCurrentId(c.id);
          return { list:cs, item:c, idx:0 };
        }
        function titleOf(messages) {
          for (var i=0;i<messages.length;i++) if (messages[i].who==="user") {
            var t = messages[i].text;
            return t.length>18 ? t.slice(0,18)+"…" : t;
          }
          return "新对话";
        }
        function render() {
          var ctx = curConv();
          var msgs = ctx.item.messages;
          document.getElementById("title").textContent = ctx.item.title;
          chat.innerHTML = "";
          if (msgs.length === 0) {
            chat.innerHTML = '<div class="empty"><div class="dot">✦</div><p>今天想聊点什么？在下方输入。</p></div>';
            return;
          }
          msgs.forEach(function(m) {
            var row = document.createElement("div");
            var side = (m.who === "ai" || m.who === "ai-thinking") ? "ai" : "user";
            row.className = "row " + side;
            var d = document.createElement("div");
            d.className = "msg " + side + (m.who === "ai-thinking" ? " thinking" : "");
            d.textContent = m.text;
            var t = document.createElement("span");
            t.className = "time"; t.textContent = m.time;
            d.appendChild(t);
            row.appendChild(d);
            chat.appendChild(row);
          });
          chat.scrollTop = chat.scrollHeight;
        }
        function renderHist() {
          var cs = loadConvs();
          var box = document.getElementById("histlist");
          box.innerHTML = "";
          if (cs.length === 0) { box.innerHTML = '<div class="hist-empty">暂无历史对话</div>'; return; }
          cs.forEach(function(c) {
            var item = document.createElement("div");
            item.className = "hist-item" + (c.id === currentId() ? " active" : "");
            var ht = document.createElement("div"); ht.className="ht"; ht.textContent = c.title;
            var hs = document.createElement("div"); hs.className="hs";
            var last = c.messages[c.messages.length-1];
            hs.textContent = (last ? last.text : "") + " · " + c.time;
            item.appendChild(ht); item.appendChild(hs);
            item.onclick = function() { setCurrentId(c.id); closeDrawer(); render(); };
            box.appendChild(item);
          });
        }
        function openDrawer() { drawer.classList.add("open"); mask.classList.add("open"); renderHist(); }
        function closeDrawer() { drawer.classList.remove("open"); mask.classList.remove("open"); }

        // 「打招呼」场景的触发判断：命中后只从通用池的 greeting 彩蛋里取（见 scenePool）
        function isRoastTriggered(t) {
          return t.indexOf("我是") >= 0 || t.indexOf("你好") >= 0;
        }
        // ===== Philo 模式：三角色云端 AI + 本地状态机 =====
        // 全部文案在 Resources/aether_presets.json（带唯一 id），身份质疑触发词见 detection.identityTriggers
        function currentCharKey() {
          var av = localStorage.getItem("aether.avatar") || "ghost";
          return CHAR_KEY_BY_AVATAR[av] || "nox";
        }
        function hasCrash(t) {
          for (var i = 0; i < CRASH_WORDS.length; i++) if (t.indexOf(CRASH_WORDS[i]) >= 0) return true;
          return false;
        }
        function hasProfane(t) {
          var low = t.toLowerCase();
          for (var i = 0; i < WHITELIST.length; i++) if (low.indexOf(WHITELIST[i]) >= 0) return false;
          for (var i = 0; i < PROFANE_WORDS.length; i++) if (low.indexOf(PROFANE_WORDS[i]) >= 0) return true;
          return false;
        }
        function isIdentityQuestion(t) {
          var low = t.toLowerCase();
          for (var i = 0; i < PHILO_IDENTITY_TRIGGERS.length; i++) if (low.indexOf(PHILO_IDENTITY_TRIGGERS[i]) >= 0) return true;
          return false;
        }
        function bumpCount(k) { var n = parseInt(localStorage.getItem(k) || "0", 10); localStorage.setItem(k, String(n + 1)); }
        function pushThinking(txt) {
          var c = curConv();
          c.item.messages.push({ text: txt, time: nowHM(), who: "ai-thinking" });
          saveConvs(c.list); render();
        }
        function popThinkingPushAi(charKey, text) {
          var c = curConv();
          if (c.item.messages.length && c.item.messages[c.item.messages.length - 1].who === "ai-thinking") c.item.messages.pop();
          c.item.messages.push({ text: text, time: nowHM(), who: "ai", char: charKey });
          localStorage.setItem("aether.lastSpeaker", charKey);
          saveConvs(c.list); render();
        }
        // ---- 场景取词：严格按规格合并「角色专属 + 通用」（scenePool 即合并规则表） ----
        // 脏话：角色专属脏话 + 通用脏话彩蛋；安慰：角色专属安慰 + 通用安慰；
        // 身份质疑：仅角色专属；互撕：仅角色专属（再按上一任角色细分）；
        // 打招呼：仅通用；日常：仅通用 general。
        // 条目结构统一为 { id, text } 或 { id, texts: [...] }，取词用 entryText 拍平。
        function scenePool(charKey, scene) {
          var ch = (P.characters && P.characters[charKey]) || {};
          var cm = P.common || {};
          if (scene === "profanity") return (ch.profanity || []).concat(cm.profanity || []);
          if (scene === "comfort")   return (ch.comfort   || []).concat(cm.comfort   || []);
          if (scene === "identity")  return (ch.identity  || []);
          if (scene === "greeting")  return (cm.greeting  || []);
          if (scene === "general")   return (cm.general   || []);
          return [];
        }
        function pickEntry(pool) { return (pool && pool.length) ? pool[Math.floor(Math.random() * pool.length)] : null; }
        // 单句条目取 text；组条目把 texts 用换行拼成一整条气泡。
        function entryText(e) {
          if (!e) return "";
          if (e.texts && e.texts.length) return e.texts.join("\\n");
          return e.text || "";
        }
        // Nox 没有互撕池（规格：不攻击别人），返回 null 后自然落到日常场景。
        function pickRivalGroup(charKey, prevKey) {
          var by = ((P.characters && P.characters[charKey]) || {}).rival || {};
          var pool = by[prevKey];
          if (!pool || !pool.length) {
            pool = [];
            for (var k in by) { if (by[k] && by[k].length) pool = pool.concat(by[k]); }
          }
          return pickEntry(pool);
        }
        function callCloud(charKey, text) {
          var c = curConv().item;
          var msgs = [];
          // 只带最近 20 条。上下文太长时模型容易转去「总结这场对话」而不是接着演。
          var from = Math.max(0, c.messages.length - 20);
          for (var i = from; i < c.messages.length; i++) {
            var m = c.messages[i];
            if (m.who === "user") { msgs.push({ role: "user", content: m.text }); continue; }
            if (m.who !== "ai" || !m.char) continue;
            // 自己说过的话不加「[名字]:」前缀。加了以后整段上下文像剧本，
            // 模型会顺着剧本写旁白（「从角色设定出发，Aetheria 会……」），而不是以第一人称回话。
            // 只有别的角色发言才带标签，用来区分说话人。
            if (m.char === charKey) msgs.push({ role: "assistant", content: m.text });
            else msgs.push({ role: "assistant", content: "[" + CHAR_NAME[m.char] + "]:" + m.text });
          }
          pushThinking("正在组织语言…");
          var reqId = ++apiSeq;
          pendingApi[reqId] = { char: charKey, text: text };
          if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.aetherBridge) {
            var sysPrompt = (P.characters && P.characters[charKey] && P.characters[charKey].system) || "";
            window.webkit.messageHandlers.aetherBridge.postMessage({ type: "api", reqId: reqId, system: sysPrompt, messages: msgs, reasoning: "" });
          }
        }
        function stripCharPrefix(s) {
          if (!s) return s;
          // 去掉模型偶尔回显的「[Cecil]:」「[Aetheria]:」「[Nox]:」前缀——来自多轮上下文里的 [角色名]: 格式，
          // 模型会把它当成回复样式照搬；不去掉会越积越多（每轮再叠加一次）。
          return s.replace(/^\\[(Cecil|Aetheria|Nox)\\]:?\\s*/, "");
        }
        window.__aetherApiResult = function(reqId, ok, text) {
          try {
            var p = pendingApi[reqId];
            delete pendingApi[reqId];
            if (!p) {
              var c0 = curConv();
              if (c0.item.messages.length && c0.item.messages[c0.item.messages.length - 1].who === "ai-thinking") c0.item.messages.pop();
              saveConvs(c0.list); render();
              return;
            }
            if (ok && text && text.trim()) { popThinkingPushAi(p.char, stripCharPrefix(text)); return; }
            // 云端失败（没联网 / 请求出错）→ 按「没开 Philo」处理：回落本地预设回复。
            var c = curConv();
            if (c.item.messages.length && c.item.messages[c.item.messages.length - 1].who === "ai-thinking") c.item.messages.pop();
            saveConvs(c.list); render();
            localReply(p.text || "");
          } catch (e) { console.error(e); }
        };
        // 状态 B（Philo 开但没网）与 C（Philo 关）的统一本地回复：
        // 按场景从「当前角色专属池 + 通用池」合并后的候选集随机取一条。
        // 场景优先级：崩溃安慰 > 脏话 > 互撕 > 身份质疑 > 打招呼 > 日常。
        function localReply(text) {
          var charKey = currentCharKey();
          var comfortKey = "aether.localComfort:" + currentId();

          // 1) 崩溃安慰（角色安慰 + 通用安慰）
          if (hasCrash(text)) {
            var comfortText = entryText(pickEntry(scenePool(charKey, "comfort")));
            pushThinking("正在陪伴您…");
            setTimeout(function() {
              localStorage.setItem(comfortKey, "1");
              bumpCount("aether.comfortCount");
              popThinkingPushAi(charKey, comfortText);
            }, 1800);
            return;
          }

          var comfortActive = localStorage.getItem(comfortKey) === "1";
          var replyText = "", delay = 900;

          // 2) 脏话（角色脏话 + 通用脏话彩蛋）；本轮已触发安慰则跳过
          if (!comfortActive && hasProfane(text)) {
            var pl = entryText(pickEntry(scenePool(charKey, "profanity")));
            if (pl) { replyText = pl; delay = 2300; }
          }
          // 3) 互撕（仅角色专属，按上一任角色细分；Nox 无此池，取不到就往下走）
          if (!replyText) {
            var last = localStorage.getItem("aether.lastSpeaker");
            if (last && last !== charKey) {
              var rg = entryText(pickRivalGroup(charKey, last));
              if (rg) { replyText = rg; delay = 1200; }
            }
          }
          // 4) 身份质疑（仅角色专属）
          if (!replyText && isIdentityQuestion(text)) {
            var il = entryText(pickEntry(scenePool(charKey, "identity")));
            if (il) { replyText = il; delay = 1000; }
          }
          // 5) 打招呼（仅通用）
          if (!replyText && isRoastTriggered(text)) {
            var gl = entryText(pickEntry(scenePool(charKey, "greeting")));
            if (gl) { replyText = gl; delay = 900; }
          }
          // 6) 日常（仅通用 general 池）
          if (!replyText) {
            replyText = entryText(pickEntry(scenePool(charKey, "general")));
            delay = logosOn ? 2600 : 900;
          }

          var thinkingText = logosOn ? "深度思考中…" : "思考中…";
          pushThinking(thinkingText);
          setTimeout(function() { popThinkingPushAi(charKey, replyText); }, delay);
        }
        function doSend() {
          var text = ta.value.trim();
          if (!text) return;
          var ctx = curConv();
          ctx.item.messages.push({ text: text, time: nowHM(), who: "user" });
          ctx.item.title = titleOf(ctx.item.messages);
          ctx.item.time = nowHM();
          saveConvs(ctx.list);
          ta.value = ""; ta.style.height = "auto"; send.disabled = true;
          render();
          // Philo 关 —— 或 Philo 开了但没联网（未配置云端）—— 都按「没开」处理，走本地预设回复。
          // Philo 真正联网时才交给云端三角色自己应对（含情绪与脏话，System Prompt 有紧急豁免）。
          if (philoOn && window.__aetherCloudConfigured === true) { callCloud(currentCharKey(), text); return; }
          localReply(text);
        }
        send.onclick = doSend;
        ta.addEventListener("input", function() {
          send.disabled = !ta.value.trim();
          ta.style.height = "auto";
          ta.style.height = Math.min(ta.scrollHeight, 140) + "px";
        });
        ta.addEventListener("keydown", function(e) {
          if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); doSend(); }
        });
        document.getElementById("clear").onclick = function() {
          var cs = loadConvs();
          var id = currentId();
          cs = cs.filter(function(c){ return c.id !== id; });
          saveConvs(cs);
          setCurrentId("");
          curConv(); // 新建一条空对话
          render();
        };
        document.getElementById("newchat").onclick = function() {
          var c = { id: Date.now().toString(36)+Math.random().toString(36).slice(2,6), title:"新对话", messages:[], time: nowHM() };
          var cs = loadConvs(); cs.unshift(c);
          saveConvs(cs); setCurrentId(c.id); render();
        };
        document.getElementById("history").onclick = openDrawer;
        document.getElementById("closeDrawer").onclick = closeDrawer;
        mask.onclick = closeDrawer;
        document.getElementById("clearAll").onclick = function() {
          saveConvs([]);
          setCurrentId("");
          curConv();
          closeDrawer();
          render();
        };
        document.getElementById("logos").onclick = function() {
          logosOn = !logosOn;
          this.classList.toggle("on", logosOn);
          document.getElementById("inputbox").classList.toggle("logos-on", logosOn);
        };
        document.getElementById("philos").onclick = function() {
          philoOn = !philoOn;
          this.classList.toggle("on", philoOn);
          document.getElementById("inputbox").classList.toggle("philo-on", philoOn);
          localStorage.setItem("aether.philoOn", philoOn ? "1" : "0");
        };
        // Aether 形象：Cecil（男）/ Aetheria（女）/ Nox（幽灵）；点头像循环切换，齿轮菜单按名选择，存本地
        var avatarVariants = ["male", "female", "ghost"];
        var avatarLabels = { male: "Cecil", female: "Aetheria", ghost: "Nox" };
        var avatarSVGs = {
          male: '<img src="data:image/svg+xml;base64," width="28" height="28">',
          female: '<img src="data:image/svg+xml;base64," width="28" height="28">',
          ghost: '<img src="data:image/svg+xml;base64," width="28" height="28">'
        };
        var avatarEl = document.getElementById("avatar");
        var avatarMenu = document.getElementById("avatarmenu");
        var avatarSetBtn = document.getElementById("avatarset");
        function applyAvatar(v) {
          if (avatarVariants.indexOf(v) < 0) v = "ghost";
          avatarEl.innerHTML = avatarSVGs[v];
          avatarEl.setAttribute("title", "Aether 形象：" + avatarLabels[v] + "（点击切换）");
          localStorage.setItem("aether.avatar", v);
          var opts = avatarMenu.querySelectorAll(".avatar-opt");
          for (var i=0;i<opts.length;i++){ opts[i].classList.toggle("active", opts[i].getAttribute("data-v") === v); }
        }
        // 齿轮菜单：列出三款形象，按名选择
        (function(){
          var html = '<div class="mh">选择 Aether 形象</div>';
          for (var i=0;i<avatarVariants.length;i++){
            var v = avatarVariants[i];
            html += '<div class="avatar-opt" data-v="'+v+'"><span class="sw">'+avatarSVGs[v]+'</span><span class="nm">'+avatarLabels[v]+'</span><span class="ck">✓</span></div>';
          }
          avatarMenu.innerHTML = html;
          var opts = avatarMenu.querySelectorAll(".avatar-opt");
          for (var j=0;j<opts.length;j++){
            opts[j].onclick = function(){ applyAvatar(this.getAttribute("data-v")); avatarMenu.style.display = "none"; };
          }
        })();
        avatarSetBtn.onclick = function(e){
          e.stopPropagation();
          avatarMenu.style.display = (avatarMenu.style.display === "block") ? "none" : "block";
        };
        document.addEventListener("click", function(e){
          if (avatarMenu.style.display === "block" && !avatarMenu.contains(e.target) && e.target !== avatarSetBtn) {
            avatarMenu.style.display = "none";
          }
        });
        avatarEl.onclick = function() {
          var cur = localStorage.getItem("aether.avatar") || "ghost";
          applyAvatar(avatarVariants[(avatarVariants.indexOf(cur) + 1) % avatarVariants.length]);
        };
        document.getElementById("philos").classList.toggle("on", philoOn);
        document.getElementById("inputbox").classList.toggle("philo-on", philoOn);
        applyAvatar(localStorage.getItem("aether.avatar") || "ghost");
        render();
      </script>
    </body>
    </html>
    """
}
